import pandas as pd
import matplotlib.pyplot as plt
import seaborn as sns
import base64
import io
import numpy as np

# Apply professional style
plt.style.use('seaborn-v0_8-whitegrid')
sns.set_palette("muted")

def fig_to_base64(fig):
    buf = io.BytesIO()
    fig.savefig(buf, format='png', bbox_inches='tight', dpi=120)
    buf.seek(0)
    return base64.b64encode(buf.read()).decode('utf-8')

# Read Data
try:
    df = pd.read_csv('/app/benchmark/data.csv')
    df['Date'] = pd.to_datetime(df['Date'])
    df = df.sort_values('Date').reset_index(drop=True)
except Exception as e:
    print(f"Error loading data: {e}")
    exit(1)

# Feature Engineering
df['Year'] = df['Date'].dt.year
df['Decade'] = (df['Year'] // 10) * 10
df['MoM_Abs_Change'] = df['Crude_Oil_Price'].diff()
df['MoM_Pct_Change'] = df['Crude_Oil_Price'].pct_change() * 100
df['YoY_Abs_Change'] = df['Crude_Oil_Price'].diff(12)
df['YoY_Pct_Change'] = df['Crude_Oil_Price'].pct_change(12) * 100

# KPIs
min_price = df['Crude_Oil_Price'].min()
max_price = df['Crude_Oil_Price'].max()
price_range = max_price - min_price

first_price = df.iloc[0]['Crude_Oil_Price']
last_price = df.iloc[-1]['Crude_Oil_Price']
num_years = (df.iloc[-1]['Date'] - df.iloc[0]['Date']).days / 365.25
cagr = ((last_price / first_price) ** (1 / num_years)) - 1
cagr_pct = cagr * 100

max_abs_change = df['MoM_Abs_Change'].abs().max()
max_abs_idx = df['MoM_Abs_Change'].abs().idxmax()
max_abs_month = df.loc[max_abs_idx, 'Date'].strftime('%Y-%m')
max_abs_val = df.loc[max_abs_idx, 'MoM_Abs_Change']

max_pct_change = df['MoM_Pct_Change'].abs().max()
max_pct_idx = df['MoM_Pct_Change'].abs().idxmax()
max_pct_month = df.loc[max_pct_idx, 'Date'].strftime('%Y-%m')
max_pct_val = df.loc[max_pct_idx, 'MoM_Pct_Change']

decade_means = df.groupby('Decade')['Crude_Oil_Price'].mean()
highest_decade = decade_means.idxmax()
highest_decade_val = decade_means.max()

std_dev = df['Crude_Oil_Price'].std()
mean_price = df['Crude_Oil_Price'].mean()
median_price = df['Crude_Oil_Price'].median()

# Generating Plots
# 1. Full Time Series
fig1, ax1 = plt.subplots(figsize=(12, 6))
ax1.plot(df['Date'], df['Crude_Oil_Price'], color='#2c3e50', linewidth=1.5)
ax1.set_title('Global Crude Oil Prices (1970–2026)', fontsize=16, pad=15)
ax1.set_ylabel('Price (USD/bbl)', fontsize=12)
ax1.set_xlabel('Year', fontsize=12)
ax1.fill_between(df['Date'], df['Crude_Oil_Price'], alpha=0.1, color='#2c3e50')
img_timeseries = fig_to_base64(fig1)
plt.close(fig1)

# 2. Decade-by-Decade Boxplot
fig2, ax2 = plt.subplots(figsize=(10, 6))
sns.boxplot(data=df, x='Decade', y='Crude_Oil_Price', palette='Blues', ax=ax2)
ax2.set_title('Price Distribution by Decade', fontsize=16, pad=15)
ax2.set_ylabel('Price (USD/bbl)', fontsize=12)
ax2.set_xlabel('Decade', fontsize=12)
img_decade = fig_to_base64(fig2)
plt.close(fig2)

# 3. Volatility (MoM % Change)
fig3, ax3 = plt.subplots(figsize=(12, 5))
ax3.plot(df['Date'], df['MoM_Pct_Change'], color='#e74c3c', linewidth=1)
ax3.axhline(0, color='black', linewidth=0.8, linestyle='--')
ax3.set_title('Month-over-Month Percentage Change', fontsize=16, pad=15)
ax3.set_ylabel('Change (%)', fontsize=12)
ax3.set_xlabel('Year', fontsize=12)
img_volatility = fig_to_base64(fig3)
plt.close(fig3)

# 4. Statistical Distribution
fig4, ax4 = plt.subplots(figsize=(10, 6))
sns.histplot(df['Crude_Oil_Price'], bins=30, kde=True, color='#3498db', ax=ax4)
ax4.set_title('Distribution of Crude Oil Prices', fontsize=16, pad=15)
ax4.set_xlabel('Price (USD/bbl)', fontsize=12)
ax4.set_ylabel('Frequency', fontsize=12)
img_distribution = fig_to_base64(fig4)
plt.close(fig4)

